import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1210, own='cte_133.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("882.d.1.A",3,"A diesel shop apprentice explains to a fleet driver, in plain words and without jargon, why the truck needs a fuel filter change. This shows:","effective oral communication with people from varied cultures and backgrounds",["avoiding the driver","using only slang","hiding the problem"],"Clear speech.")
H("882.d.1.A",4,"Which oral communication habit works best when a customer describes a symptom?","Listening, then repeating the symptom back to confirm it",["Interrupting often","Guessing the cause at once","Looking away"],"Active listening.")
H("882.d.1.B",3,"Marisol writes a repair order that lists the complaint, the cause found and the fix, in clear sentences. This shows:","effective written communication in the diesel shop",["no record keeping","sloppy notes","verbal only"],"Clear writing.")
H("882.d.1.B",4,"A written repair order should include the complaint, the cause and the correction so that:","the next technician can follow the work",["nobody can understand it","the bill is bigger","the work is hidden"],"Document the three Cs.")
H("882.d.1.C",3,"A student measures a bolt in millimeters and a shaft in inches and converts between them with a chart. She is showing:","math skills and precision measurement with metric and customary units",["guessing sizes","no measuring","only counting"],"Convert units.")
H("882.d.1.C",4,"A 25.4 mm bolt is how many inches long?","1 inch",["2 inches","0.5 inch","10 inches"],"25.4 mm = 1 in.")
H("882.d.2.A",3,"A student points out the turbocharger, the injectors and the cylinder head on a diesel engine. She is:","describing the function of major components of diesel powered vehicles",["naming gas engine parts only","naming body panels","naming tires"],"Know the parts.")
H("882.d.2.A",4,"In a diesel engine, fuel is ignited by:","heat created by compressing the air in the cylinder",["a spark plug","a match","a battery coil"],"Compression ignition.")
H("882.d.2.B",3,"A technician explains that the air brake system, the steering gear and the transmission make up parts of a heavy truck's chassis. She is:","describing the function of chassis components",["describing the radio","describing the paint","describing the seats"],"Chassis parts.")
H("882.d.2.B",4,"On a heavy truck, air brakes are commonly used because they:","can be applied reliably over long trailers and heavy loads",["use no air","are the lightest","need no maintenance"],"Air brakes suit heavy loads.")
H("882.d.2.C",3,"Using a wiring schematic, a technician traces the circuit for a faulty headlight on a semi tractor. She is:","locating, reading and interpreting documents such as schematics, charts and diagrams",["ignoring diagrams","guessing the wire","painting the truck"],"Read schematics.")
H("882.d.2.C",4,"A schematic symbol that looks like a zigzag usually stands for a:","resistor",["battery","ground","switch"],"Zigzag resistor.")
H("882.d.2.D",3,"A technician uses a micrometer to measure a crankshaft journal and compares the reading to the specification. She is demonstrating:","precision measurement procedures to diagnose component wear",["eyeballing parts","guessing wear","skipping specs"],"Measure wear.")
H("882.d.2.D",4,"If a journal measures below the minimum specification, the technician should:","replace or machine the part as directed",["ignore it","paint it","reuse it anyway"],"Out of spec.")
H("882.d.3.A",3,"Before using a floor jack under a truck frame, a technician sets jack stands and checks that the load is stable. She is:","describing and demonstrating safe use of hand and power tools and equipment",["rushing the job","skipping stands","working under a jack only"],"Safe lifting.")
H("882.d.3.A",4,"Why should a technician never rely on a jack alone to support a vehicle?","Jacks can fail or slip, so stands are needed",["Jacks are too heavy","Stands are expensive","Jacks never fail"],"Use stands.")
H("882.d.3.B",3,"A shop collects used engine oil and coolant in labeled containers for a licensed recycler. This is:","proper handling and disposal of environmentally hazardous materials",["dumping waste","pouring oil down the drain","burning waste in the lot"],"Hazmat disposal.")
H("882.d.3.B",4,"Used coolant should not be poured on the ground because it:","is toxic and contaminates soil and water",["is clean","is harmless","is free"],"Coolant toxicity.")
H("882.d.3.C",3,"An instructor shows students a selective catalytic reduction system that uses diesel exhaust fluid to cut emissions. She is describing:","new and emerging diesel technologies",["outdated parts","a carburetor","a steam engine"],"Emissions tech.")
H("882.d.3.C",4,"Diesel exhaust fluid is injected into the exhaust to:","reduce nitrogen oxide emissions",["increase soot","add power","cool the engine"],"DEF reduces NOx.")
H("882.d.3.D",3,"A student plugs a scan tool into the truck's diagnostic port to read fault codes. She is:","identifying and using diagnostic tools and equipment",["guessing the fault","ignoring codes","using a ruler"],"Scan tools.")
H("882.d.3.D",4,"A fault code tells the technician:","where to begin testing, not always which part has failed",["exactly what part to buy","nothing at all","that the truck is fine"],"Codes guide testing.")
H("882.d.3.E",3,"A technician explains that hydraulic fluid carries force through lines to move a lift and relieves pressure before work. She is describing:","hydraulic and pneumatic properties, controls and safety",["engine knock","tire wear","paint chemistry"],"Fluid power.")
H("882.d.3.E",4,"Before disconnecting a hydraulic line, the technician should first:","relieve the system pressure",["loosen the fitting at full pressure","heat the line","start the engine"],"Relieve pressure.")
H("882.d.4.A",3,"A parts clerk logs a fuel-injector order, shelves it by number and checks the bin counts weekly. She is describing:","parts management procedures such as ordering, stocking and locating",["throwing parts out","ignoring inventory","guessing counts"],"Parts management.")
H("882.d.4.A",4,"Keeping stock counts accurate helps a shop avoid:","running out of common parts and delaying repairs",["having every part","fewer customers","cleaner shelves"],"Inventory accuracy.")
H("882.d.4.B",3,"An apprentice removes a cylinder head, inspects the gasket surface for warping and replaces the head gasket. She is demonstrating:","procedures for removal, inspection and replacement of engine components",["painting the head","guessing damage","skipping inspection"],"Engine service.")
H("882.d.4.B",4,"A straightedge and feeler gauge are used on a cylinder head to check:","flatness of the gasket surface",["paint thickness","oil color","tire pressure"],"Check warpage.")
H("882.d.4.C",3,"A technician inspects the turbocharger's boost hose, the intercooler and the air filter on a hauling rig. She is describing:","inspection and maintenance of ancillary systems such as air intake and exhaust",["tire rotation","painting","radio repair"],"Ancillary systems.")
H("882.d.4.C",4,"A cracked boost hose can cause:","power loss and black smoke from leaking boost",["better fuel economy","higher boost","cleaner exhaust"],"Boost leak.")
H("882.d.4.D",3,"Using a multimeter, a technician measures 12 V across a circuit with 4 amps flowing and calculates the resistance. She is applying:","electrical circuit testing, including Ohm's law",["no electrical rules","guessing","mechanical wear"],"Ohm's law.")
H("882.d.4.D",4,"A circuit has 12 volts and 4 amps of current. Its resistance is:","3 ohms",["48 ohms","8 ohms","0.33 ohm"],"R = V/I = 3.")
H("882.d.4.E",3,"A technician follows a wiring diagram to find where a ground wire connects on a tractor cab. She is demonstrating:","wiring diagrams and related symbols and service procedures",["ignoring diagrams","guessing the ground","using no tools"],"Use the diagram.")
H("882.d.4.E",4,"Wiring diagrams use symbols so that technicians can:","read a circuit without tracing every wire by hand",["avoid reading","hide wiring","skip testing"],"Symbols simplify.")
H("882.d.4.F",3,"A technician checks the lift gate hydraulics and the power take-off on a utility truck for leaks. She is:","discussing procedures to inspect and maintain auxiliary systems",["ignoring auxiliary systems","painting","guessing"],"Auxiliary systems.")
H("882.d.4.F",4,"A power take-off is used to:","run auxiliary equipment such as pumps from the engine",["steer the truck","cool the cab","light the cab"],"PTO use.")
H("882.d.4.G",3,"A technician inspects the clutch, driveshaft and brake linings on a dump truck and adjusts as needed. She is:","inspecting and maintaining chassis and power train components",["washing the truck","painting","guessing"],"Power train service.")
H("882.d.4.G",4,"A worn U-joint in a driveshaft commonly causes:","vibration and a clunk during acceleration",["quiet driving","better fuel economy","a cooler engine"],"U-joint wear.")
H("882.d.4.H",3,"A technician flushes a radiator, tests the coolant and replaces an oil filter on a diesel engine. She is performing:","inspection and maintenance of cooling and lubrication systems",["tire service","paint repair","glass repair"],"Cooling and lube.")
H("882.d.4.H",4,"Mixing the wrong coolant type in a diesel engine can cause:","corrosion and clogging in the cooling system",["better cooling","more power","cleaner coolant"],"Coolant compatibility.")
H("882.d.4.I",3,"A shop supervisor does a quarterly walk-through to check eyewash stations, fire extinguishers and waste storage. She is demonstrating:","the process to perform regular audits and inspections to maintain compliance",["skipping safety","guessing","ignoring rules"],"Safety audits.")
H("882.d.4.I",4,"Regular safety audits in a diesel shop help to:","find hazards before someone gets hurt or the shop is fined",["increase injuries","avoid training","hide problems"],"Prevent harm.")
H("883.d.1.A",3,"A senior diesel tech briefs a new hire on a job in short, clear spoken steps and asks for the plan back. This shows:","effective oral communication with people from varied backgrounds",["mumbling","avoiding questions","ignoring the new hire"],"Oral clarity.")
H("883.d.1.A",4,"During a shift change, a technician reports an unfinished repair to the next person by:","explaining what was done and what remains",["leaving without a word","hiding the problem","blaming others"],"Handoff.")
H("883.d.1.B",3,"After diagnosing a no-start, a technician writes a clear report listing readings, parts and labor. This shows:","effective written communication with people from varied backgrounds",["a vague note","no notes","a drawing only"],"Written clarity.")
H("883.d.1.B",4,"Detailed written notes on a repair help later when:","the same problem returns or a warranty claim is filed",["nothing matters","the truck is sold","no one reads them"],"Records matter.")
H("883.d.1.C",3,"A technician converts 1.5 inches to millimeters while checking a bore diameter on a heavy-duty engine. She is demonstrating:","mathematical skills and precision measurements using metric and customary systems",["estimating by eye","skipping math","guessing"],"Converting.")
H("883.d.1.C",4,"A 1.5-inch bore is about how many millimeters?","38.1 mm",["15 mm","58 mm","25.4 mm"],"1.5 × 25.4 = 38.1.")
H("883.d.2.A",3,"On an excavator, a technician identifies the hydraulic pump, the swing motor and the final drive and states what each does. She is describing:","the function of the major components of diesel powered vehicles and equipment",["only the body panels","only the seat","only the paint"],"Equipment components.")
H("883.d.2.A",4,"The hydraulic pump on diesel equipment is driven by the engine and:","moves hydraulic fluid to power cylinders and motors",["lights the cab","cools the engine","cleans the air"],"Pump function.")
H("883.d.2.B",3,"A technician runs a test on an engine with low power, narrows it to restricted fuel flow and records the cause. She is performing:","system diagnostics and failure analyses",["guessing","skipping tests","replacing every part"],"Diagnose systematically.")
H("883.d.2.B",4,"A failure analysis goes beyond fixing a broken part by:","finding why it failed so it doesn't happen again",["ignoring the cause","blaming the driver","hiding the failure"],"Root cause.")
H("883.d.2.C",3,"A technician explains how the steering gear, the air brake chambers and the transmission work together in a heavy truck. She is describing:","the function of chassis components such as braking, steering and transmission",["radio parts","seat parts","paint parts"],"Chassis function.")
H("883.d.2.C",4,"A slack adjuster on an air brake is used to:","keep the brake shoe clearance in range",["steer the truck","cool the engine","fill the tank"],"Brake adjustment.")
H("883.d.2.D",3,"A technician troubleshoots a hydraulic dump bed that won't lift and finds the PTO won't engage. She is:","diagnosing, repairing and replacing auxiliary equipment such as power take-offs and hydraulics",["washing the truck","ignoring the bed","painting the bed"],"Auxiliary repair.")
H("883.d.2.D",4,"If a hydraulic cylinder drifts down while holding a load, the likely cause is:","internal leakage past a worn seal",["too much oil only","a clean filter","a full tank"],"Seal leakage.")
H("883.d.2.E",3,"A technician reads a hydraulic schematic to find where the relief valve sits in a loader circuit. She is:","locating, reading and interpreting schematics, charts and diagrams",["skipping diagrams","guessing the valve","guessing the pump"],"Hydraulic schematics.")
H("883.d.2.E",4,"On a hydraulic schematic, the relief valve is shown to:","limit maximum system pressure",["raise pressure","cool the fluid","filter the fluid"],"Relief valve.")
H("883.d.2.F",3,"A technician measures piston-to-bore clearance with a dial bore gauge and compares to the published spec. She is:","performing precision measurements and using published specifications to diagnose component wear",["eyeballing","skipping specs","guessing"],"Spec comparison.")
H("883.d.2.F",4,"Published specifications are used because they:","give the allowed limits so a technician knows when a part is worn out",["are suggestions only","replace measuring","are secret"],"Spec limits.")
H("883.d.3.A",3,"Before using an impact wrench on a lug nut, a technician checks the socket and wears eye protection. She is:","demonstrating safe use of hand and power tools and equipment",["rushing","skipping safety glasses","using the wrong socket"],"Tool safety.")
H("883.d.3.A",4,"A cracked impact socket should be:","taken out of service and replaced",["used anyway","taped","repainted"],"Damaged tools.")
H("883.d.3.B",3,"A mobile mechanic bags oily rags and takes used filters to a recycler instead of the dumpster. She is:","demonstrating the proper handling and disposal of environmentally hazardous materials",["ignoring rules","hiding waste","burning waste"],"Disposal.")
H("883.d.3.B",4,"Used oil filters are drained before disposal to:","keep leftover oil from reaching landfill",["save time","add weight","cause leaks"],"Drain filters.")
H("883.d.3.C",3,"A shop trains techs on a hybrid diesel-electric transit bus and an engine with a diesel particulate filter. This describes:","emerging diesel technologies",["outdated methods","hand tools only","buggy repair"],"Emerging diesel.")
H("883.d.3.C",4,"A diesel particulate filter is used to:","trap soot from the exhaust",["add soot","cool the engine","raise noise"],"DPF function.")
H("883.d.3.D",3,"A technician connects a manufacturer's laptop software to the engine control module to run a cylinder cutout test. She is:","performing the proper use of diagnostic tools and equipment",["guessing","using a hammer","ignoring the computer"],"Diagnostic software.")
H("883.d.3.D",4,"A cylinder cutout test helps a technician find:","a weak or misfiring cylinder",["a flat tire","a loose seat","a bad radio"],"Misfire test.")
H("883.d.3.E",3,"A technician explains why compressed air and hydraulic oil need pressure-rated hoses and how stored pressure can hurt a person. She is demonstrating:","knowledge of hydraulic and pneumatic properties, controls and safety",["no knowledge of pressure","ignoring hoses","ignoring safety"],"Fluid power safety.")
H("883.d.3.E",4,"A pinhole leak in a high-pressure hydraulic hose can:","inject fluid through skin, so it should be found with cardboard, not a hand",["be checked by hand","be safe","never occur"],"Injection injury.")
H("883.d.4.A",3,"A parts lead enters a new filter shipment, assigns a bin and orders replacements when stock hits a minimum. She is:","demonstrating parts inventory management such as ordering, stocking and locating",["ignoring stock","guessing","throwing out parts"],"Inventory.")
H("883.d.4.A",4,"A reorder point is set so that a shop:","orders before the last part runs out",["orders after running out","never orders","orders too much"],"Reorder point.")
H("883.d.4.B",3,"After a compression test shows one weak cylinder, a technician pulls the head, replaces a burned valve and reassembles per spec. She is demonstrating:","procedures for diagnosis, removal, repair and replacement of engine components",["painting the head","skipping tests","guessing"],"Engine repair.")
H("883.d.4.B",4,"After reassembling a cylinder head, bolts are tightened in sequence with a torque wrench to:","clamp the gasket evenly and prevent leaks",["loosen the gasket","make noise","save time"],"Torque sequence.")
H("883.d.4.C",3,"A technician diagnoses an air-brake system that builds pressure slowly and finds a leaking air line. She is:","diagnosing, servicing and repairing diesel equipment systems such as braking and steering",["ignoring leaks","painting lines","guessing"],"Brake system repair.")
H("883.d.4.C",4,"Slow air pressure build-up on a truck can point to:","an air leak or a weak compressor",["a full tank","a clean line","a good seal"],"Air build-up.")
H("883.d.4.D",3,"A technician tests the alternator and battery when a truck's lights dim and the starter drags. She is:","diagnosing and repairing electrical and electronic systems such as starting and charging",["painting","guessing","ignoring volts"],"Charging system.")
H("883.d.4.D",4,"A battery that reads 11.8 volts at rest is:","partly discharged and should be charged and tested",["fully charged","new","perfect"],"Low resting voltage.")
H("883.d.4.E",3,"A technician checks refrigerant pressures and the compressor clutch on a cab air-conditioning system. She is:","demonstrating an understanding of the diagnosis, service and repair of air-conditioning systems",["washing the cab","ignoring cooling","painting vents"],"AC service.")
H("883.d.4.E",4,"Air-conditioning refrigerant must be recovered rather than vented because it:","harms the environment and is regulated",["is harmless","is free","helps the air"],"Recover refrigerant.")
H("883.d.4.F",3,"After a hard shift, a technician diagnoses a slipping clutch and inspects the transmission and differential on a tractor. She is:","diagnosing, servicing and repairing chassis and power train systems",["ignoring the clutch","painting parts","guessing"],"Drivetrain service.")
H("883.d.4.F",4,"A burning smell and a slipping clutch point to:","a worn or overheated clutch disc",["a new clutch","a clean disc","a full tank"],"Clutch wear.")
H("883.d.4.G",3,"A technician replaces a leaking water pump and tests the oil pump pressure on a diesel engine. She is:","servicing and repairing cooling and lubrication systems such as water pumps and oil pumps",["painting","guessing","ignoring pumps"],"Pump service.")
H("883.d.4.G",4,"Low oil pressure on a running diesel engine should be treated as:","an urgent warning to shut the engine down and find the cause",["a minor note","normal","an option"],"Low oil pressure.")
H("883.d.4.H",3,"A technician connects a pressure gauge and a scan tool to a diesel fuel system to check rail pressure. She is:","using appropriate diagnostic equipment on various diesel equipment systems",["guessing","using a ruler","skipping tools"],"Use the right equipment.")
H("883.d.4.H",4,"Comparing measured fuel rail pressure to the specification lets a technician:","decide whether the fuel system is working correctly",["ignore the system","avoid testing","skip the spec"],"Compare to spec.")
H("883.d.4.I",3,"A shop foreman logs fire extinguisher checks and updates the hazard communication binder every month. She is:","performing regular audits and inspections to maintain compliance with regulations",["ignoring rules","skipping logs","guessing"],"Compliance audits.")
H("883.d.4.I",4,"Keeping audit records helps a diesel shop:","show inspectors it follows safety and environmental rules",["hide problems","avoid inspections","skip training"],"Proof of compliance.")
